import React, { useEffect, useState } from "react";
import { useTheme } from "../context/ThemeContext";
import { getMyReports } from "../api/thesis";

import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  Tooltip,
  ResponsiveContainer,
  CartesianGrid,
} from "recharts";

const Dashboard = () => {
  const { colors } = useTheme();
  const [reports, setReports] = useState([]);

  useEffect(() => {
    getMyReports().then(setReports);
  }, []);

  const chartData = reports.map((r) => ({
    date: new Date(r.uploaded_at).toLocaleDateString(),
    plagiarism: r.plagiarism_score,
    ai: r.ai_score,
  }));

  return (
    <div
      style={{
        backgroundColor: colors.pageBg,
        minHeight: "100vh",
        padding: "40px 20px",
        color: colors.text,
      }}
    >
      <div style={{ maxWidth: "1100px", margin: "0 auto" }}>
        <h1 style={{ fontSize: "32px", marginBottom: "30px" }}>
          My Dashboard
        </h1>

        {/* 📈 LINE CHART */}
        <div
          style={{
            backgroundColor: colors.cardBg,
            padding: "24px",
            borderRadius: "16px",
            marginBottom: "40px",
          }}
        >
          <h3 style={{ marginBottom: "16px" }}>
            Plagiarism & AI Score Over Time
          </h3>

          <ResponsiveContainer width="100%" height={300}>
            <LineChart data={chartData}>
              <CartesianGrid strokeDasharray="3 3" />
              <XAxis dataKey="date" />
              <YAxis />
              <Tooltip />
              <Line
                type="monotone"
                dataKey="plagiarism"
                stroke="#f87171"
                strokeWidth={2}
                name="Plagiarism %"
              />
              <Line
                type="monotone"
                dataKey="ai"
                stroke="#fbbf24"
                strokeWidth={2}
                name="AI %"
              />
            </LineChart>
          </ResponsiveContainer>
        </div>

        {/* 🧾 TABLE */}
        <div
          style={{
            backgroundColor: colors.cardBg,
            padding: "24px",
            borderRadius: "16px",
          }}
        >
          <h3 style={{ marginBottom: "16px" }}>My Uploads</h3>

          <table width="100%">
            <thead>
              <tr>
                <th align="left">File</th>
                <th>Plagiarism</th>
                <th>AI</th>
                <th>Status</th>
              </tr>
            </thead>
            <tbody>
              {reports.map((r) => (
                <tr key={r.id}>
                  <td>{r.file.split("/").pop()}</td>
                  <td>{r.plagiarism_score}%</td>
                  <td>{r.ai_score}%</td>
                  <td>{r.status}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;
